import sys

def is_transformable(s, t):
    # Check if the lengths are compatible
    if len(s) < len(t):
        return False

    # Count the occurrences of 'A', 'B', 'C' in both s and t
    count_s = [0, 0, 0]
    count_t = [0, 0, 0]

    for char in s:
        count_s[ord(char) - ord('A')] += 1

    for char in t:
        count_t[ord(char) - ord('A')] += 1

    # Check if we can remove 'AAA' from s
    while count_s[0] >= 3:
        count_s[0] -= 3

    # Check if the remaining counts in s can match t
    for i in range(3):
        if count_s[i] < count_t[i]:
            return False

    return True

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    S = data[0]
    T = data[1]
    Q = int(data[2])

    queries = []
    for i in range(Q):
        ai = int(data[3 + 4 * i]) - 1
        bi = int(data[4 + 4 * i]) - 1
        ci = int(data[5 + 4 * i]) - 1
        di = int(data[6 + 4 * i]) - 1
        queries.append((ai, bi, ci, di))

    results = []
    for ai, bi, ci, di in queries:
        if is_transformable(S[ai:bi+1], T[ci:di+1]):
            results.append('1')
        else:
            results.append('0')

    print(''.join(results))

if __name__ == "__main__":
    main()
